create table if not exists public.enterprise_partner_allocations (id uuid primary key default gen_random_uuid(), network_id uuid not null references public.enterprise_partner_networks(id) on delete cascade, partner_business_id uuid not null references public.businesses(id) on delete cascade, campaign_id uuid references public.enterprise_partner_campaigns(id) on delete set null, allocation_type text not null check(allocation_type in ('promotion','single_use_access','preferred','points','contest')), quantity numeric not null default 0 check(quantity>=0), budget_cents bigint not null default 0 check(budget_cents>=0), status text not null default 'planned' check(status in ('planned','active','paused','completed','cancelled')), rationale text, created_at timestamptz not null default now(), activated_at timestamptz, completed_at timestamptz);
create index if not exists enterprise_partner_allocations_network_idx on public.enterprise_partner_allocations(network_id,status);
create index if not exists enterprise_partner_allocations_partner_idx on public.enterprise_partner_allocations(partner_business_id,status);
alter table public.enterprise_partner_allocations enable row level security;
create or replace function public.create_partner_allocation(p_network_id uuid,p_partner_business_id uuid,p_campaign_id uuid,p_type text,p_quantity numeric,p_budget_cents bigint,p_rationale text) returns public.enterprise_partner_allocations language plpgsql security definer set search_path=public as $$ declare a public.enterprise_partner_allocations; begin if not exists(select 1 from public.enterprise_partner_networks where id=p_network_id and owner_business_id in(select business_id from public.business_members where user_id=auth.uid())) then raise exception 'network access denied'; end if; if not exists(select 1 from public.enterprise_partner_network_members where network_id=p_network_id and partner_business_id=p_partner_business_id and status='active') then raise exception 'partner not active'; end if; insert into public.enterprise_partner_allocations(network_id,partner_business_id,campaign_id,allocation_type,quantity,budget_cents,rationale) values(p_network_id,p_partner_business_id,p_campaign_id,p_type,greatest(0,p_quantity),greatest(0,p_budget_cents),p_rationale) returning * into a; return a; end $$;
revoke all on function public.create_partner_allocation(uuid,uuid,uuid,text,numeric,bigint,text) from public,anon; grant execute on function public.create_partner_allocation(uuid,uuid,uuid,text,numeric,bigint,text) to authenticated;
create or replace function public.activate_partner_allocation(p_allocation_id uuid) returns public.enterprise_partner_allocations language plpgsql security definer set search_path=public as $$ declare a public.enterprise_partner_allocations; begin update public.enterprise_partner_allocations x set status='active',activated_at=now() where x.id=p_allocation_id and x.network_id in(select n.id from public.enterprise_partner_networks n where n.owner_business_id in(select business_id from public.business_members where user_id=auth.uid())) and x.status='planned' returning x.* into a; if not found then raise exception 'allocation unavailable'; end if; return a; end $$;
revoke all on function public.activate_partner_allocation(uuid) from public,anon; grant execute on function public.activate_partner_allocation(uuid) to authenticated;
create or replace function public.get_partner_allocation_roi(p_network_id uuid,p_start date default current_date-30,p_end date default current_date) returns table(partner_business_id uuid,allocation_type text,allocated_budget_cents bigint,outcome_value bigint,efficiency numeric) language sql security definer set search_path=public as $$ select a.partner_business_id,a.allocation_type,sum(a.budget_cents)::bigint,sum(coalesce(o.check_ins,0)+coalesce(o.preferred_uses,0)+coalesce(o.access_redemptions,0)+coalesce(o.promotion_redemptions,0))::bigint,case when sum(a.budget_cents)>0 then round((sum(coalesce(o.check_ins,0)+coalesce(o.preferred_uses,0)+coalesce(o.access_redemptions,0)+coalesce(o.promotion_redemptions,0))::numeric*100)/sum(a.budget_cents),4) else 0 end from enterprise_partner_allocations a left join enterprise_partner_campaigns c on c.id=a.campaign_id left join enterprise_partner_campaign_outcomes o on o.campaign_id=c.id and o.partner_business_id=a.partner_business_id and o.metric_date between p_start and p_end where a.network_id=p_network_id and a.status in('active','completed') and exists(select 1 from enterprise_partner_networks n where n.id=a.network_id and n.owner_business_id in(select business_id from business_members where user_id=auth.uid())) group by a.partner_business_id,a.allocation_type $$;
revoke all on function public.get_partner_allocation_roi(uuid,date,date) from public,anon; grant execute on function public.get_partner_allocation_roi(uuid,date,date) to authenticated;
